for(const url of ["http://127.0.0.1:3000/","http://127.0.0.1/","http://omar-webos/"]){const response=await fetch(url,{headers:{Host:"omar-webos",Origin:"http://omar-webos"},signal:AbortSignal.timeout(8000)});const body=await response.text();console.log(JSON.stringify({url,status:response.status,contentType:response.headers.get("content-type"),bodyPreview:response.status===200?body.slice(0,40):body.slice(0,1200)}));}
